"""Opt-in live PCM input + native truncation check. Test utterance generated by Foundry, in RAM only."""

import asyncio
import base64
import json

import websockets
from azure.ai.projects.aio import AIProjectClient
from azure.identity.aio import AzureCliCredential

from app.config import Settings


async def make_test_utterance(settings: Settings) -> bytes:
    audio = bytearray()
    async with (
        asyncio.timeout(35),
        AzureCliCredential(tenant_id=settings.tenant_id or None, process_timeout=15) as credential,
        AIProjectClient(settings.project_endpoint, credential=credential, allow_preview=True) as client,
        client.beta.voice_agents.realtime.connect(
            agent_name=settings.agent_name, extra_query={"store": "false"},
        ) as conn,
    ):
        async for event in conn:
            if event.type == "session.updated":
                await conn.response.create(response={
                    "conversation": "none", "tool_choice": "none", "output_modalities": ["audio"],
                    "instructions": (
                        "This is an audio-input integration test. Speak exactly this test question and "
                        "nothing else: What is the latest news about Microsoft Foundry voice agents?"
                    ),
                    "max_output_tokens": 100,
                })
            elif event.type == "response.output_audio.delta":
                audio.extend(event.delta)
            elif event.type == "error":
                raise RuntimeError(f"Native test utterance failed: {event.error.code}")
            elif event.type == "response.done":
                if event.response.status != "completed" or not audio:
                    raise RuntimeError("The native test utterance did not complete.")
                return bytes(audio)
    raise RuntimeError("No native test utterance was returned.")


async def main():
    settings = Settings.load()
    utterance = await make_test_utterance(settings)
    print(f"Native test utterance: {len(utterance) / 48000:.2f}s, in memory only.")
    stream_task = None
    audio_items: dict[str, int] = {}
    interrupted = False
    saw_transcript = False
    saw_sources = False
    async with (
        asyncio.timeout(100),
        websockets.connect(f"ws://127.0.0.1:{settings.port}/api/voice",
                           origin=f"http://127.0.0.1:{settings.port}", max_size=512_000) as ws,
    ):
        async def stream():
            pcm = utterance + bytes(48000)
            for offset in range(0, len(pcm), 960):
                await ws.send(pcm[offset:offset + 960])
                await asyncio.sleep(.020)

        try:
            async for raw in ws:
                event = json.loads(raw)
                kind = event["type"]
                if kind == "ready":
                    stream_task = asyncio.create_task(stream())
                elif kind == "interrupt":
                    await ws.send(json.dumps({
                        "type": "playback", "turn": event["turn"], "items": [
                            {"item_id": item, "content_index": index, "audio_end_ms": 0}
                            for item, index in audio_items.items()
                        ],
                    }))
                elif kind == "transcript" and event["role"] == "user":
                    saw_transcript = True
                    print("Native input transcription received; content not logged.")
                elif kind == "evidence":
                    saw_sources = bool(event["sources"])
                    print("Retrieved source count:", len(event["sources"]))
                elif kind == "audio" and event["turn"] > 0:
                    audio_items[event["item_id"]] = event["content_index"]
                    if not interrupted:
                        interrupted = True
                        print("Native audio received before interruption:", len(base64.b64decode(event["data"])))
                        await ws.send(json.dumps({"type": "interrupt"}))
                elif kind == "playback_truncated":
                    if not (saw_transcript and saw_sources and interrupted and event["audio_end_ms"] == 0):
                        raise RuntimeError("Incomplete native input/evidence/truncation verification.")
                    print("Native server acknowledged conversation truncation at 0 ms.")
                    await ws.send(json.dumps({"type": "end"}))
                    return
                elif kind == "error":
                    raise RuntimeError(f"{event['code']}: {event['message']}")
        finally:
            if stream_task:
                stream_task.cancel()
                await asyncio.gather(stream_task, return_exceptions=True)
    raise RuntimeError("The voice-input check did not complete.")


if __name__ == "__main__":
    asyncio.run(main())
